1	//! Recurrent state for Qwen3.5 linear attention layers.
2	//!
3	//! Each linear attention layer maintains:
4	//! - Recurrent state: [local_value_heads, key_head_dim, value_head_dim] f32, V contiguous ([H,K,V])
5	//! - Conv state: [local_qkv_dim × (conv_kernel_dim - 1)] bf16
6	//!
7	//! Under TP, value heads (and fused qkv channels) are sharded across ranks,
8	//! so every rank owns its own recurrent/conv state; these states are never
9	//! all-reduced.
10	
11	use anyhow::Result;
12	use cudarc::driver::CudaSlice;
13	use cudarc::driver::DevicePtrMut;
14	use pegainfer_core::tensor::DeviceContext;
15	use pegainfer_core::tensor::DeviceVec;
16	
17	use super::config::Config35;
18	use super::config::LocalGeometry;
19	
20	/// Per-layer recurrent state for a single linear attention layer.
21	pub(crate) struct LayerRecurrentState {
22	    /// Recurrent state matrix: [local_value_heads * key_head_dim * value_head_dim] f32
23	    /// Stored as f32 per mamba_ssm_dtype="float32" in config.
24	    pub(crate) state: CudaSlice<f32>,
25	    /// Conv1d state buffer: [local_linear_qkv_dim * (conv_kernel_dim - 1)] bf16
26	    /// Stores the last (kernel_dim - 1) inputs for causal conv1d.
27	    pub(crate) conv_state: DeviceVec,
28	}
29	
30	/// Recurrent state for all linear attention layers.
31	pub(crate) struct RecurrentState {
32	    pub(crate) layers: Vec<LayerRecurrentState>,
33	    /// Number of tokens processed so far (for prefill/decode tracking).
34	    pub(crate) seq_len: usize,
35	}
36	
37	/// Device-side tables of per-slot recurrent-state pointers.
38	///
39	/// Batched linear decode kernels take a device array of pointers per linear
40	/// layer. The underlying `CudaSlice` allocations inside `RecurrentState` stay
41	/// at fixed device addresses for the request lifetime, so these tables should
42	/// be built once per slot/request and then reused across decode tokens.
43	///
44	/// Where the row set changes between steps (eager TP decode), allocate once at
45	/// capacity with `with_capacity` and `refill_from_recurrent_refs` the live
46	/// rows each step: H2D copies into the existing tables, no per-step allocation.
47	pub(crate) struct LinearStatePointerTables {
48	    pub(crate) state_ptrs: Vec<CudaSlice<u64>>,
49	    pub(crate) conv_state_ptrs: Vec<CudaSlice<u64>>,
50	    capacity: usize,
51	}
52	
53	/// Per-layer element counts shared by allocation and reservation:
54	/// (linear layers, f32 state elements, bf16 conv elements).
55	fn per_layer_dims(config: &Config35, geometry: LocalGeometry) -> (usize, usize, usize) {
56	    let num_linear_layers = config.num_hidden_layers - config.num_full_attention_layers();
57	    let state_size = geometry.local_linear_num_value_heads()
58	        * config.linear_key_head_dim
59	        * config.linear_value_head_dim;
60	    let conv_state_size = geometry.local_linear_qkv_dim() * (config.linear_conv_kernel_dim - 1);
61	    (num_linear_layers, state_size, conv_state_size)
62	}
63	
64	impl RecurrentState {
65	    /// Allocate zeroed recurrent state for all linear attention layers.
66	    pub(crate) fn new(
67	        ctx: &DeviceContext,
68	        config: &Config35,
69	        geometry: LocalGeometry,
70	    ) -> Result<Self> {
71	        let (num_linear_layers, state_size, conv_state_size) = per_layer_dims(config, geometry);
72	
73	        let mut layers = Vec::with_capacity(num_linear_layers);
74	        for _ in 0..num_linear_layers {
75	            let state: CudaSlice<f32> = ctx
76	                .stream
77	                .alloc_zeros(state_size)
78	                .map_err(|e| anyhow::anyhow!("Alloc recurrent state failed: {}", e))?;
79	            layers.push(LayerRecurrentState {
80	                state,
81	                conv_state: DeviceVec::zeros(ctx, conv_state_size)?,
82	            });
83	        }
84	
85	        Ok(Self { layers, seq_len: 0 })
86	    }
87	
88	    /// Copy one complete target-model recurrent state into this allocation.
89	    pub(crate) fn copy_from(&mut self, ctx: &DeviceContext, src: &Self) -> Result<()> {
90	        anyhow::ensure!(
91	            self.layers.len() == src.layers.len(),
92	            "Qwen3.5 recurrent copy layer mismatch: dst={}, src={}",
93	            self.layers.len(),
94	            src.layers.len()
95	        );
96	        for (layer_idx, (dst, src)) in self.layers.iter_mut().zip(&src.layers).enumerate() {
97	            ctx.stream
98	                .memcpy_dtod(&src.state, &mut dst.state)
99	                .map_err(|e| anyhow::anyhow!("copy recurrent layer {layer_idx}: {e}"))?;
100	            ctx.stream
101	                .memcpy_dtod(&src.conv_state.data, &mut dst.conv_state.data)
102	                .map_err(|e| anyhow::anyhow!("copy conv state layer {layer_idx}: {e}"))?;
103	        }
104	        self.seq_len = src.seq_len;
105	        Ok(())
106	    }
107	}
108	
109	impl LinearStatePointerTables {
110	    /// Allocate zeroed per-layer tables with room for `capacity` rows. Rows
111	    /// carry no pointers until `refill_from_recurrent_refs` writes them.
112	    pub(crate) fn with_capacity(
113	        ctx: &DeviceContext,
114	        config: &Config35,
115	        capacity: usize,
116	        label: &str,
117	    ) -> Result<Self> {
118	        let num_linear_layers = config.num_hidden_layers - config.num_full_attention_layers();
119	        let mut state_ptrs = Vec::with_capacity(num_linear_layers);
120	        let mut conv_state_ptrs = Vec::with_capacity(num_linear_layers);
121	        for layer_idx in 0..num_linear_layers {
122	            state_ptrs.push(ctx.stream.alloc_zeros::<u64>(capacity).map_err(|e| {
123	                anyhow::anyhow!("alloc {label} linear state pointer table {layer_idx}: {e}")
124	            })?);
125	            conv_state_ptrs.push(ctx.stream.alloc_zeros::<u64>(capacity).map_err(|e| {
126	                anyhow::anyhow!("alloc {label} conv state pointer table {layer_idx}: {e}")
127	            })?);
128	        }
129	        Ok(Self {
130	            state_ptrs,
131	            conv_state_ptrs,
132	            capacity,
133	        })
134	    }
135	
136	    /// Tables sized exactly to `batch_size` rows, filled once.
137	    pub(crate) fn from_recurrent_refs(
138	        ctx: &DeviceContext,
139	        config: &Config35,
140	        recurrent_states: &mut [&mut RecurrentState],
141	        batch_size: usize,
142	        label: &str,
143	    ) -> Result<Self> {
144	        let mut tables = Self::with_capacity(ctx, config, batch_size, label)?;
145	        tables.refill_from_recurrent_refs(ctx, recurrent_states, batch_size, label)?;
146	        Ok(tables)
147	    }
148	
149	    /// Overwrite rows `0..batch_size` of every layer table with the current
150	    /// state addresses of `recurrent_states`. Copies into the existing
151	    /// allocations only; rows past `batch_size` keep whatever they held and
152	    /// must stay unaddressed (the kernels are handed `batch_size`).
153	    pub(crate) fn refill_from_recurrent_refs(
154	        &mut self,
155	        ctx: &DeviceContext,
156	        recurrent_states: &mut [&mut RecurrentState],
157	        batch_size: usize,
158	        label: &str,
159	    ) -> Result<()> {
160	        anyhow::ensure!(
161	            batch_size <= recurrent_states.len(),
162	            "{label} pointer table batch {batch_size} exceeds recurrent refs {}",
163	            recurrent_states.len()
164	        );
165	        anyhow::ensure!(
166	            batch_size <= self.capacity,
167	            "{label} pointer table batch {batch_size} exceeds capacity {}",
168	            self.capacity
169	        );
170	        let tables = self
171	            .state_ptrs
172	            .iter_mut()
173	            .zip(self.conv_state_ptrs.iter_mut());
174	        for (layer_idx, (state_table, conv_table)) in tables.enumerate() {
175	            let mut state_ptrs = Vec::with_capacity(batch_size);
176	            let mut conv_state_ptrs = Vec::with_capacity(batch_size);
177	            for slot in recurrent_states.iter_mut().take(batch_size) {
178	                let state_ptr = {
179	                    let (ptr, _guard) = slot.layers[layer_idx].state.device_ptr_mut(&ctx.stream);
180	                    ptr
181	                };
182	                let conv_ptr = {
183	                    let (ptr, _guard) = slot.layers[layer_idx]
184	                        .conv_state
185	                        .data
186	                        .device_ptr_mut(&ctx.stream);
187	                    ptr
188	                };
189	                state_ptrs.push(state_ptr);
190	                conv_state_ptrs.push(conv_ptr);
191	            }
192	            ctx.stream
193	                .memcpy_htod(state_ptrs.as_slice(), state_table)
194	                .map_err(|e| {
195	                    anyhow::anyhow!("copy {label} linear state pointer table {layer_idx}: {e}")
196	                })?;
197	            ctx.stream
198	                .memcpy_htod(conv_state_ptrs.as_slice(), conv_table)
199	                .map_err(|e| {
200	                    anyhow::anyhow!("copy {label} conv state pointer table {layer_idx}: {e}")
201	                })?;
202	        }
203	        Ok(())
204	    }
205	
206	    pub(crate) fn validate_for(
207	        &self,
208	        config: &Config35,
209	        batch_size: usize,
210	        label: &str,
211	    ) -> Result<()> {
212	        let num_linear_layers = config.num_hidden_layers - config.num_full_attention_layers();
213	        anyhow::ensure!(
214	            self.capacity >= batch_size,
215	            "{label} pointer table capacity {} is smaller than batch {batch_size}",
216	            self.capacity
217	        );
218	        anyhow::ensure!(
219	            self.state_ptrs.len() == num_linear_layers
220	                && self.conv_state_ptrs.len() == num_linear_layers,
221	            "{label} pointer table layer count mismatch: state={}, conv={}, expected={num_linear_layers}",
222	            self.state_ptrs.len(),
223	            self.conv_state_ptrs.len()
224	        );
225	        Ok(())
226	    }
227	}
228	
229	/// Device bytes of one request's recurrent state.
230	pub(crate) fn bytes_per_request(config: &Config35, geometry: LocalGeometry) -> usize {
231	    let (num_linear_layers, state_size, conv_state_size) = per_layer_dims(config, geometry);
232	    num_linear_layers
233	        * (state_size * std::mem::size_of::<f32>()
234	            + conv_state_size * std::mem::size_of::<half::bf16>())
235	}
236	
237	impl RecurrentState {
238	    pub(crate) fn allocation_bytes(config: &Config35, geometry: LocalGeometry) -> usize {
239	        bytes_per_request(config, geometry)
240	    }
241	}
242	
243	#[cfg(test)]
244	mod tests {
245	    #[test]
246	    fn qwen35_4b_recurrent_allocation_is_49_125_mib() {
247	        let bytes = 24
248	            * (32 * 128 * 128 * std::mem::size_of::<f32>()
249	                + 8192 * 3 * std::mem::size_of::<half::bf16>());
250	        assert_eq!(bytes, 49 * 1024 * 1024 + 128 * 1024);
251	    }
252	}
