229	/// Device bytes of one request's recurrent state.
230	pub(crate) fn bytes_per_request(config: &Config35, geometry: LocalGeometry) -> usize {
231	    let (num_linear_layers, state_size, conv_state_size) = per_layer_dims(config, geometry);
232	    num_linear_layers
233	        * (state_size * std::mem::size_of::<f32>()
234	            + conv_state_size * std::mem::size_of::<half::bf16>())
235	}
236	
237	impl RecurrentState {
238	    pub(crate) fn allocation_bytes(config: &Config35, geometry: LocalGeometry) -> usize {
239	        bytes_per_request(config, geometry)
240	    }
241	}
