    /// one point.
    fn bf16_ulp_distance(a: bf16, b: bf16) -> u32 {
        let ordered = |value: bf16| {
            let bits = i32::from(value.to_bits());
            if bits & 0x8000 != 0 {
                -(bits & 0x7fff)
            } else {
                bits
            }
        };
        ordered(a).abs_diff(ordered(b))
    }

