652	        let ordered = |value: bf16| {
653	            let bits = i32::from(value.to_bits());
654	            if bits & 0x8000 != 0 {
655	                -(bits & 0x7fff)
656	            } else {
657	                bits
658	            }
659	        };
660	        ordered(a).abs_diff(ordered(b))
661	    }
