498	/// GDN key head dim baked into the kernels: the decode kernel's tiling and shared
499	/// memory layout (`GDR_KEY_DIM` in `gated_delta_rule.cu`) and the chunk-wise
500	/// prefill's Triton AOT specialization keys both hardcode it.
501	pub const GDN_AOT_KEY_HEAD_DIM: usize = 128;
502	
503	/// GDN value head dim, baked in for the same reasons (`GDR_VAL_DIM`). It is also
504	/// the width of the per-head gated norm's weight.
505	pub const GDN_AOT_VALUE_HEAD_DIM: usize = 128;
506	
507	/// Largest depthwise conv1d kernel the in-tree conv carries state for:
508	/// `conv1d.cu` sizes its state as `kernel_size - 1 <= 3` taps.
509	pub const LINEAR_CONV_MAX_KERNEL_DIM: usize = 4;
510	
511	/// One Gated DeltaNet decode step for a batch of requests.
512	///
513	/// `qkv` is the **post-conv1d, post-SiLU** projection, `[q | k | v]` per token:
514	/// `num_key_heads * key_dim` query columns, then the same number of key columns,
515	/// then `num_value_heads * val_dim` value columns. `state_ptrs` is a device array
516	/// of per-request states, each `[num_value_heads, key_dim, val_dim]` f32 with
517	/// `val_dim` contiguous (the FLA `[H, K, V]` convention); a request's state is
518	/// read and updated in place. `output` is `num_value_heads * val_dim` wide.
519	///
520	/// Head dims must be the baked-in ones ([`GDN_AOT_KEY_HEAD_DIM`],
521	/// [`GDN_AOT_VALUE_HEAD_DIM`]); head counts are free, so a different value-head
522	/// count needs no rebuild.
523	///
524	/// `b_proj` and `a_proj` may each be one band of a fused beta/alpha projection;
525	/// their slot stride is then the tensor they are a band of.
526	#[allow(clippy::too_many_arguments)]
527	pub fn gated_delta_rule_decode_batch_into<'a>(
528	    ctx: &DeviceContext,
529	    qkv: &HiddenStates,
530	    b_proj: impl Into<Columns<'a>>,
531	    a_proj: impl Into<Columns<'a>>,
532	    dt_bias: &DeviceVec,
533	    a_log: &CudaSlice<f32>,
534	    state_ptrs: &CudaSlice<u64>,
535	    output: &mut HiddenStates,
536	    batch_size: usize,
537	    num_key_heads: usize,
538	    num_value_heads: usize,
539	    key_dim: usize,
540	    val_dim: usize,
541	) {
542	    let b_proj = b_proj.into();
543	    let a_proj = a_proj.into();
544	    b_proj.assert_in_row("gated_delta_rule_decode b_proj");
545	    a_proj.assert_in_row("gated_delta_rule_decode a_proj");
546	    assert_eq!(qkv.seq_len, batch_size);
547	    assert_eq!(b_proj.states.seq_len, batch_size);
548	    assert_eq!(a_proj.states.seq_len, batch_size);
549	    assert_eq!(output.seq_len, batch_size);
550	    assert!(
551	        num_key_heads > 0 && num_value_heads > 0 && num_value_heads.is_multiple_of(num_key_heads),
552	        "value heads {num_value_heads} must be a positive whole number of \
553	         key-head groups of {num_key_heads}"
554	    );
555	    assert_eq!(
556	        qkv.hidden_dim,
557	        2 * num_key_heads * key_dim + num_value_heads * val_dim
558	    );
559	    assert_eq!(b_proj.width, num_value_heads);
560	    assert_eq!(a_proj.width, num_value_heads);
561	    assert_eq!(output.hidden_dim, num_value_heads * val_dim);
562	    assert_eq!(dt_bias.len, num_value_heads);
563	    assert_eq!(a_log.len(), num_value_heads);
564	    assert_eq!(key_dim, GDN_AOT_KEY_HEAD_DIM);
565	    assert_eq!(val_dim, GDN_AOT_VALUE_HEAD_DIM);
566	    assert!(state_ptrs.len() >= batch_size);
567	
568	    let (b_base, _gb) = b_proj.states.data.device_ptr(&ctx.stream);
569	    let b_ptr = b_base + (b_proj.col * std::mem::size_of::<bf16>()) as u64;
570	    let (a_base, _ga) = a_proj.states.data.device_ptr(&ctx.stream);
571	    let a_ptr = a_base + (a_proj.col * std::mem::size_of::<bf16>()) as u64;
572	    let (qkv_ptr, _gq) = qkv.data.device_ptr(&ctx.stream);
573	    let (dt_ptr, _gdt) = dt_bias.data.device_ptr(&ctx.stream);
574	    let (alog_ptr, _gal) = a_log.device_ptr(&ctx.stream);
575	    let (state_ptrs, _gsp) = state_ptrs.device_ptr(&ctx.stream);
576	    let (o_ptr, _go) = output.data.device_ptr_mut(&ctx.stream);
577	
578	    unsafe {
579	        ffi::gated_delta_rule_decode_batch_cuda(
580	            qkv_ptr as *const ffi::Half,
581	            b_ptr as *const ffi::Half,
582	            a_ptr as *const ffi::Half,
583	            dt_ptr as *const ffi::Half,
584	            alog_ptr as *const f32,
585	            state_ptrs as *const u64,
586	            o_ptr as *mut ffi::Half,
587	            batch_size as i32,
588	            num_key_heads as i32,
589	            num_value_heads as i32,
590	            key_dim as i32,
591	            val_dim as i32,
592	            b_proj.states.hidden_dim as i32,
593	            a_proj.states.hidden_dim as i32,
594	            ctx.stream.cu_stream(),
595	        );
596	    }
597	}
