599	/// One causal depthwise conv1d decode step for a batch of requests, fused with
600	/// the SiLU the GDN block consumes.
601	///
602	/// `x` is the **pre-conv** projection row, `num_channels` wide. `conv_weight` is
603	/// the flattened `[num_channels, 1, kernel_size]` depthwise weight. `conv_state_ptrs`
604	/// is a device array of per-request states, each `num_channels * (kernel_size - 1)`
605	/// bf16 taps holding the previous inputs oldest-first; it is updated in place from
606	/// `x`, so `kernel_size` must not exceed [`LINEAR_CONV_MAX_KERNEL_DIM`]. `out` is
607	/// `silu(bf16(conv))`, rounded exactly like the reference (`conv1d` then `silu` in
608	/// bf16), not a fused `silu(sum)`.
609	///
610	/// Slots of the conv input stride by the tensor's own row width, so `x` may be
611	/// the qkv band of a fused qkv+z projection. The conv output is this operator's
612	/// own buffer and keeps the band's width as its slot stride.
613	pub fn conv1d_decode_batch_into<'a>(
614	    ctx: &DeviceContext,
615	    x: impl Into<Columns<'a>>,
616	    conv_weight: &DeviceVec,
617	    conv_state_ptrs: &CudaSlice<u64>,
618	    out: &mut HiddenStates,
619	    kernel_size: usize,
620	) {
621	    let x = x.into();
622	    x.assert_in_row("conv1d_decode x");
623	    let batch_size = x.states.seq_len;
624	    let num_channels = x.width;
625	    assert_eq!(out.hidden_dim, num_channels);
626	    assert_eq!(out.seq_len, batch_size);
