fn batch_decode_kernels_graph(
    &self,
    kv_buffer: &cudarc::driver::CudaSlice<half::bf16>,
    layout: &KvLayout,
    padded_bs: usize,
    prefill_attn_plan: Option<&ops::PrefillPagedPlan>,
    linear_state_ptrs: &[CudaSlice<u64>],
    linear_conv_state_ptrs: &[CudaSlice<u64>],
    bufs: &mut BatchDecodeBuffers35,
) -> Result<()> {
    let eps = self.config.rms_norm_eps;

    ops::embedding_batch(
        &self.ctx,
        &self.embed_tokens,
        &bufs.token_ids_d,
        &mut bufs.hidden,
    )?;

    let mut linear_idx = 0usize;
    let mut full_idx = 0usize;
    for layer in &self.layers {
        ops::rms_norm_batch_offset_into(
            &self.ctx,
            &bufs.hidden,
            &layer.input_layernorm,
            eps,
            &mut bufs.normed,
        )?;

        match &layer.attn {
            LayerKind::FullAttention(attn) => {
                match prefill_attn_plan {
                    Some(plan) => self.batch_decode_full_attention_via_prefill(
                        attn, kv_buffer, layout, plan, full_idx, padded_bs, bufs,
                    )?,
                    None => self.batch_decode_full_attention(
                        attn, kv_buffer, layout, full_idx, padded_bs, bufs,
                    )?,
                }
                full_idx += 1;
            }
            LayerKind::LinearAttention(attn) => {
                self.batch_decode_linear_attention_slots(
                    attn,
                    &linear_state_ptrs[linear_idx],
                    &linear_conv_state_ptrs[linear_idx],
                    padded_bs,
                    bufs,
                )?;
                linear_idx += 1;
            }
        }

        ops::add_batch_into(
            &self.ctx,
            &bufs.hidden,
            &bufs.attn_results,
            &mut bufs.hidden_mid,
        )?;

        ops::rms_norm_batch_offset_into(
            &self.ctx,
            &bufs.hidden_mid,
            &layer.post_attention_layernorm,
            eps,
            &mut bufs.normed,
        )?;

        ops::gemm_into(
            &self.ctx,
            &layer.mlp.gate_up_proj,
            &bufs.normed,
            &mut bufs.gate_up_out,
        );
        ops::silu_mul_fused_batch_into(&self.ctx, &bufs.gate_up_out, &mut bufs.act_out)?;
        ops::gemm_into(
            &self.ctx,
            &layer.mlp.down_proj,
            &bufs.act_out,
            &mut bufs.mlp_out,
        );
        self.all_reduce_hidden(&mut bufs.mlp_out)?;

        ops::add_batch_into(&self.ctx, &bufs.hidden_mid, &bufs.mlp_out, &mut bufs.hidden)?;
    }

    ops::rms_norm_batch_offset_into(
        &self.ctx,
        &bufs.hidden,
        &self.norm,
        eps,
        &mut bufs.normed,
    )?;
    self.output_logits_into(&bufs.normed, &mut bufs.logits)?;
    debug_assert_eq!(bufs.logits.seq_len, padded_bs);

    Ok(())
}

fn batch_decode_batched_hybrid_kernels(
    &self,
    kv_buffer: &cudarc::driver::CudaSlice<half::bf16>,
    layout: &KvLayout,
    plan: &ops::PrefillPagedPlan,
    bs: usize,
    linear_state_ptrs: &[CudaSlice<u64>],
    linear_conv_state_ptrs: &[CudaSlice<u64>],
    bufs: &mut BatchDecodeBuffers35,
) -> Result<()> {
    let eps = self.config.rms_norm_eps;

    ops::embedding_batch(
        &self.ctx,
        &self.embed_tokens,
        &bufs.token_ids_d,
        &mut bufs.hidden,
    )?;

    }

    fn batch_decode_mlp_tail(
        &self,
        layer: &TransformerBlock35,
        bufs: &mut BatchDecodeBuffers35,
        eps: f32,
    ) -> Result<()> {
        ops::add_batch_into(
            &self.ctx,
            &bufs.hidden,
            &bufs.attn_results,
            &mut bufs.hidden_mid,
        )?;

        ops::rms_norm_batch_offset_into(
            &self.ctx,
            &bufs.hidden_mid,
            &layer.post_attention_layernorm,
            eps,
            &mut bufs.normed,
        )?;

        ops::gemm_into(
            &self.ctx,
            &layer.mlp.gate_up_proj,
            &bufs.normed,
            &mut bufs.gate_up_out,
        );
        ops::silu_mul_fused_batch_into(&self.ctx, &bufs.gate_up_out, &mut bufs.act_out)?;
        ops::gemm_into(
            &self.ctx,
            &layer.mlp.down_proj,
            &bufs.act_out,
            &mut bufs.mlp_out,
        );

        ops::add_batch_into(&self.ctx, &bufs.hidden_mid, &bufs.mlp_out, &mut bufs.hidden)
    }

    /// Linear attention decode over slot-indexed recurrent state.
    ///
    /// Iterates 0..`padded_bs`. Real requests are in 0..real_bs; padding slots
    /// (real_bs..padded_bs) run but their output columns are ignored by the caller.
    /// All GPU addresses are stable per slot index, making this CUDA Graph safe.
    fn batch_decode_linear_attention_slots(
        &self,
        attn: &LinearAttentionLayer,
        state_ptrs: &CudaSlice<u64>,
        conv_state_ptrs: &CudaSlice<u64>,
        padded_bs: usize,
        bufs: &mut BatchDecodeBuffers35,
    ) -> Result<()> {
        let geom = self.geometry;
        let qkv_dim = geom.local_linear_qkv_dim();
        let z_dim = geom.local_linear_z_dim();
        let value_heads = geom.local_linear_num_value_heads();

        // One GEMM per fused group, then each consumer reads its own band. The
        // row order is the one the loader stacked the weights in.
        ops::gemm_into(&self.ctx, &attn.in_proj_qkvz, &bufs.normed, &mut bufs.qkvz);
        ops::gemm_into(&self.ctx, &attn.in_proj_ba, &bufs.normed, &mut bufs.ba);

        ops::conv1d_decode_batch_into(
            &self.ctx,
            bufs.qkvz.columns(0, qkv_dim),
            &attn.conv1d_weight,
            conv_state_ptrs,
            &mut bufs.qkv_conv,
            self.config.linear_conv_kernel_dim,
        );
        ops::gated_delta_rule_decode_batch_into(
            &self.ctx,
            &bufs.qkv_conv,
            bufs.ba.columns(0, value_heads),
            bufs.ba.columns(value_heads, value_heads),
            &attn.dt_bias,
            &attn.a_log,
            state_ptrs,
            &mut bufs.gdr_out,
            padded_bs,
            geom.local_linear_num_key_heads(),
            value_heads,
            self.config.linear_key_head_dim,
            self.config.linear_value_head_dim,
        );

        ops::rms_norm_gated_batch_into(
            &self.ctx,
            &bufs.gdr_out,
            &attn.norm_weight,
            bufs.qkvz.columns(qkv_dim, z_dim),
            &mut bufs.normed_gated,
            value_heads,
            self.config.linear_value_head_dim,
            self.config.rms_norm_eps,
            ops::GatedNormActivation::Silu,
        );
        ops::gemm_into(
            &self.ctx,
            &attn.out_proj,
            &bufs.normed_gated,
            &mut bufs.attn_results,
        );
        self.all_reduce_hidden(&mut bufs.attn_results)?;
        Ok(())
    }
}

